window.MOTIF_CATALOG_CHUNKS[88]={"cards":[{"id":"MEJE-KW-006601","row_version":1,"title":"어두운 과거가 만든 인물","original":"Dark and Troubled Past","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"과거의 큰 상처나 비극이 현재 인물의 태도와 선택에 오래 남아 있다. 사건을 말하지 않아도 행동과 복장이 그 흔적을 암시한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006601/index.html"},{"id":"MEJE-KW-006602","row_version":1,"title":"다크 카바레","original":"Dark Cabaret","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"카바레의 무대 감각에 고딕과 펑크 계열 음악의 어두운 분위기를 섞은 음악 양식. 익살스러운 공연성과 음산한 정서가 함께 들린다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-006602/index.html"},{"id":"MEJE-KW-006603","row_version":1,"title":"불 꺼진 건물 안의 총격전","original":"Darkened Building Shootout","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물들이 어두운 실내에서 서로의 위치를 짐작하며 총격을 주고받는다. 빛과 소리의 짧은 단서가 긴장을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006603/index.html"},{"id":"MEJE-KW-006604","row_version":4,"title":"더 어둡고 거칠어진 후속 이야기","original":"Darker and Edgier","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"기존 작품이나 시리즈의 새 이야기가 폭력과 냉소를 늘려 전체 분위기를 더 무겁게 바꾼다. 변화의 폭이 인물과 세계의 읽는 방식을 바꾼다. 원작의 분위기를 팬이 비극적으로 바꾸는 경우 밝은 원작을 어둡게 바꾼 팬 창작에서 같은 변화를 볼 수 있다. 판타지에 공포와 냉소를 강하게 더한 장르적 결과는 다크 판타지다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006604/index.html"},{"id":"MEJE-KW-006605","row_version":1,"title":"아프리카를 미지의 위험으로만 그리기","original":"Darkest Africa","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"식민지 시대 모험물의 시선이 아프리카의 다양한 지역과 사람을 하나의 신비하고 위협적인 공간으로 뭉뚱그린다. 실제 대륙의 다양성을 지우는 재현으로 구분한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006605/index.html"},{"id":"MEJE-KW-006606","row_version":2,"title":"모든 것이 무너진 최악의 순간","original":"Darkest Hour","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"이야기 중간이나 후반에 주인공의 선택지가 거의 사라지고 희망도 보이지 않는 시점. 이후의 결단이나 반전이 이 낮은 지점에서 힘을 얻는다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006606/index.html"},{"id":"MEJE-KW-006608","row_version":1,"title":"밝은 원작을 어둡게 바꾼 팬 창작","original":"Dark Fic","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"본래 가벼운 작품의 인물과 사건을 팬이 비극이나 공포가 두드러진 이야기로 다시 쓴다. 원작의 분위기를 뒤집는 해석이 창작의 중심이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-006608/index.html"},{"id":"MEJE-KW-006609","row_version":1,"title":"예상을 깬 무명 배우 캐스팅","original":"Darkhorse Casting","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"큰 역할에 유명 배우 대신 대중에게 잘 알려지지 않은 배우를 기용한다. 익숙한 스타 이미지 없이 배역을 새롭게 받아들이게 한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006609/index.html"},{"id":"MEJE-KW-006610","row_version":2,"title":"뒤늦게 빛나는 형제자매","original":"Dark Horse Sibling","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"가족 안에서 주목받지 못하던 형제자매가 뜻밖의 능력과 성과를 드러낸다. 기존의 우열 관계와 가족의 기대가 흔들린다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006610/index.html"},{"id":"MEJE-KW-006611","row_version":1,"title":"두 강자를 제친 예상 밖의 승자","original":"Dark Horse Victory","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"모두가 주목한 두 경쟁자가 서로에게만 집중하는 사이 제삼의 경쟁자가 이긴다. 무시받던 인물이 판의 결과를 뒤집는다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006611/index.html"},{"id":"MEJE-KW-006612","row_version":4,"title":"어둠을 악의 신호로 쓰기","original":"Dark Is Evil","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"빛이 없는 공간과 검은 색조를 악역이나 위험의 상징으로 연결한다. 익숙한 시각 약속이며 실제 어둠이나 색에 도덕적 성질이 있다는 뜻은 아니다. 어둠을 악의 표지로 쓰는 선택은 작품의 톤을 더 어둡고 거칠어진 후속 이야기 방향으로 이끌 수 있다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-006612/index.html"},{"id":"MEJE-KW-006613","row_version":2,"title":"어둠의 힘을 써도 악하지 않은 존재","original":"Dark Is Not Evil","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"검은 외형이나 그림자 능력 때문에 악해 보이는 인물·종족이 실제로는 선한 선택을 한다. 색과 능력을 도덕성의 증거로 여기는 기대를 뒤집는다. 어둠을 공포의 신호로 쓰는 어둠 속에 들어가면 닥치는 위험은 어두운 외형만으로 도덕성을 판단하는 기대를 만든다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-006613/index.html"},{"id":"MEJE-KW-006614","row_version":1,"title":"생명 유지 장치에 의존하는 암흑 군주","original":"Dark Lord on Life Support","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"큰 부상이나 힘의 상실을 겪은 악역이 장치나 다른 육체에 의지해 살아남는다. 현재의 약점과 되찾을 힘이 함께 긴장을 만든다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006614/index.html"},{"id":"MEJE-KW-006615","row_version":2,"title":"구원을 약속하며 잔혹한 수단을 쓰는 지도자","original":"Dark Messiah","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"망가진 세계를 바꾸겠다고 나선 인물이 평화로운 미래를 내세우면서도 심각한 해악을 수단으로 받아들인다. 구원의 약속과 행동의 대가가 충돌한다. 선한 목표를 내세우며 강압을 쓰는 행동은 위협으로 선행을 강요하는 인물의 논리와 맞닿는다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006615/index.html"},{"id":"MEJE-KW-006616","row_version":3,"title":"악역의 연인","original":"Dark Mistress","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"악역과 친밀한 관계에 있는 인물이 그의 계획에 동조하거나 거부하며 서사에 얽힌다. 연인이라는 역할 뒤에 독자적인 동기와 선택이 달라질 수 있다. 악역의 연인이 영웅이라면 영웅과 악역 사이의 공개된 연애 감정의 대립과 끌림이 함께 생긴다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006616/index.html"},{"id":"MEJE-KW-006617","row_version":2,"title":"어둠 속에 들어가면 닥치는 위험","original":"Darkness Equals Death","aliases":[],"kind":"keyword","facet_id":"ML-F19","node_kind":null,"parent_id":null,"tag_path":["ML-F19"],"summary":"공포 이야기에서 불빛 없는 장소에 들어가는 순간 습격이나 불길한 사건을 예상하게 만든다. 빛의 부재가 위험의 신호가 된다. 빛이 돌아와도 위협이 사라지지 않으면 대낮에 펼쳐지는 공포의 인상으로 바뀐다.","accent":"#9B7F74","tab":"#9A6A55","facet":"정서·톤","bookmark":"분류축","entry_url":"cards/MEJE-KW-006617/index.html"},{"id":"MEJE-KW-006618","row_version":1,"title":"어둠을 과장한 이름","original":"\"Darkness von Gothick\" Name","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"고딕풍 인물에게 검정·그림자·밤을 연상시키는 이름을 붙여 성격과 분위기를 곧바로 알린다. 이름의 과장이 진지함이나 농담으로 읽힌다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-006618/index.html"},{"id":"MEJE-KW-006619","row_version":1,"title":"밝은 작품을 어둡게 비튼 패러디","original":"Dark Parody","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"원작의 경쾌한 인물과 사건을 잔혹하거나 우울한 결과로 바꿔 웃음과 불편함을 함께 만든다. 익숙한 이야기를 어둡게 뒤집는 패러디다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-006619/index.html"},{"id":"MEJE-KW-006620","row_version":2,"title":"슬프게 되돌아온 밝은 노래","original":"Dark Reprise","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"앞에서 즐겁게 들렸던 노래나 선율이 뒤에서 같은 형태로 돌아와 상실과 변화를 느끼게 한다. 반복된 음악의 뜻이 이야기와 함께 달라진다. 밝은 노래가 슬프게 되풀이되는 방식과 달리 어두운 곡의 중간만 잠깐 밝아지는 경우는 어두운 노래에 잠깐 밝아지는 구간이다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-006620/index.html"},{"id":"MEJE-KW-006621","row_version":1,"title":"숨기고 싶은 어두운 비밀","original":"Dark Secret","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 남에게 알려지면 삶이 달라질 것이라 여기는 과거의 사실을 감춘다. 비밀의 실제 무게와 그것을 두려워하는 마음은 다를 수 있다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-006621/index.html"},{"id":"MEJE-KW-006622","row_version":2,"title":"위협으로 선행을 강요하는 인물","original":"Dark Shepherd","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"타인을 선한 방향으로 돌리려는 인물이 설득 대신 두려움과 강압을 사용한다. 옳은 목적을 내세워도 수단이 관계와 판단을 뒤틀 수 있다. 강압을 넘어 세계를 구한다는 목표로 잔혹한 수단까지 정당화하면 구원을 약속하며 잔혹한 수단을 쓰는 지도자의 모습이 된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006622/index.html"},{"id":"MEJE-KW-006623","row_version":2,"title":"어두운 노래에 잠깐 밝아지는 구간","original":"Dark Song, Lighter Bridge","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"우울한 곡의 중간에 밝거나 애틋한 선율을 짧게 넣었다가 다시 어두운 흐름으로 돌아간다. 순간의 대비가 본래의 정서를 더 선명하게 만든다. 짧은 밝은 구간이 나중에 어두운 뜻으로 되돌아오면 슬프게 되돌아온 밝은 노래과도 연결된다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-006623/index.html"},{"id":"MEJE-KW-006624","row_version":1,"title":"다크 웨이브","original":"Dark Wave","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"고딕 록의 우울한 정서를 신시사이저 중심의 뉴웨이브 음악과 결합한 장르다. 기타보다 전자음의 비중이 큰 어둡고 몽환적인 소리가 특징이다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-006624/index.html"},{"id":"MEJE-KW-006625","row_version":2,"title":"현실의 뒤틀린 그림자인 어두운 세계","original":"Dark World","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"익숙한 현실과 닮았지만 건물과 거리, 삶의 모습이 쇠락한 평행세계를 그린다. 들어간 인물이 자기 세계의 불안한 반영을 마주한다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-006625/index.html"},{"id":"MEJE-KW-006626","row_version":1,"title":"미워하는 사람의 사진에 던지는 다트","original":"Dartboard of Hate","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"직접 맞설 수 없는 상대에 대한 분노를 사진이 붙은 다트판에 화살을 던지며 푼다. 안전한 물건에 감정을 옮겨 관계의 적의를 드러낸다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006626/index.html"},{"id":"MEJE-KW-006627","row_version":1,"title":"달마 인형","original":"Daruma Doll","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"바닥에 무게를 두어 쓰러져도 다시 서는 일본의 전통 인형이다. 소원을 빌고 이뤄 가는 과정과 끈기의 상징으로 이야기 속에 놓인다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-006627/index.html"},{"id":"MEJE-KW-006628","row_version":1,"title":"유전적 적합성만 따지는 배우자 선택","original":"Darwinist Desire","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 상대의 사랑이나 성격보다 자녀에게 물려줄 것으로 믿는 형질을 배우자 선택의 유일한 기준으로 삼는다. 사람을 유전적 가치로 재단하는 사고가 관계를 왜곡한다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-006628/index.html"},{"id":"MEJE-KW-006629","row_version":1,"title":"달려들며 공격하기","original":"Dash Attack","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 제자리에서 공격하지 않고 목표를 향해 빠르게 이동하며 타격한다. 달리는 속도와 충격을 한 동작에 결합한 전투 방식이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006629/index.html"},{"id":"MEJE-KW-006630","row_version":1,"title":"긴 세월을 압축해 따라가는 이야기","original":"Dashed Plot Line","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"몇 달에서 수십 년에 걸친 사건을 짧은 분량에 담아 여러 번 시간을 건너뛴다. 개별 사건보다 세월 전체가 인물과 세계를 바꾸는 흐름이 중요하다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006630/index.html"},{"id":"MEJE-KW-006631","row_version":1,"title":"산타의 순록 이름을 틀리기","original":"Dasher, Dancer, Prancer, and Nixon","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 널리 알려진 산타의 순록 이름을 말하다 비슷한 소리의 엉뚱한 이름을 섞는다. 익숙한 목록을 기억하지 못하는 실수가 농담이 된다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-006631/index.html"},{"id":"MEJE-KW-006632","row_version":2,"title":"매력적인 히스패닉 무법자","original":"Dashing Hispanic","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"모험물이나 판타지에서 히스패닉 문화권 또는 그에 대응하는 가상 문화권의 인물을 재치 있고 우아한 싸움꾼으로 묘사하는 전형. 문화적 배경을 하나의 성격으로 환원하는 관습이라는 점을 함께 드러낸다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006632/index.html"},{"id":"MEJE-KW-006633","row_version":2,"title":"교양 있어 보이는 중절모","original":"Dashingly Dapper Derby","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"둥근 챙의 보울러 모자를 쓴 인물을 세련되고 점잖은 사람처럼 보이게 한다. 모자의 시대적 인상이 인물의 사회적 분위기를 만든다. 같은 보울러 모자를 악역에게 씌우면 악당의 둥근 중절모의 인상이 생긴다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-006633/index.html"},{"id":"MEJE-KW-006634","row_version":1,"title":"멋을 낸 높이 솟은 머리","original":"Dashing Pompadour","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"앞머리를 높이 빗어 올린 퐁파두르 스타일을 자신감과 반항기의 표식으로 쓴다. 공들인 머리 모양이 인물의 태도를 먼저 알린다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-006634/index.html"},{"id":"MEJE-KW-006635","row_version":2,"title":"악당의 둥근 중절모","original":"Dastardly Dapper Derby","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"보울러 모자의 단정한 외형을 악역에게 씌워 예의 바른 겉모습과 위협적인 행동을 대비시킨다. 같은 모자가 맥락에 따라 반대 인상을 낳는다. 보울러 모자가 위협 대신 단정한 교양을 나타낼 때는 교양 있어 보이는 중절모으로 읽힌다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-006635/index.html"},{"id":"MEJE-KW-006636","row_version":1,"title":"콧수염을 꼬는 옛 무대 악당","original":"Dastardly Whiplash","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"과장된 표정과 복장, 비열한 계획으로 관객이 즉시 알아보는 고전 멜로드라마식 악역이다. 인물의 정교한 내면보다 공개적인 악당 이미지가 앞선다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-006636/index.html"},{"id":"MEJE-KW-006637","row_version":2,"title":"정보를 담는 수정 결정","original":"Data Crystal","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"미래 세계에서 투명한 결정체에 방대한 자료를 저장하고 읽는다. 보석처럼 보이는 물건이 작은 정보 저장장치가 된다. 비밀 정보가 담긴 수정 결정이 여러 인물의 쟁탈 대상이 되면 모두가 찾는 비밀 데이터 저장장치으로 쓰인다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-006637/index.html"},{"id":"MEJE-KW-006638","row_version":2,"title":"모두가 찾는 비밀 데이터 저장장치","original":"Data Drive MacGuffin","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"중요한 정보가 담긴 작은 저장장치를 여러 세력이 쫓는다. 내용보다 누가 먼저 손에 넣느냐가 사건을 움직이는 서사적 물건이다. 서로 쫓는 저장장치가 투명한 결정으로 만들어졌다면 정보를 담는 수정 결정의 외형을 지닌다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-006638/index.html"},{"id":"MEJE-KW-006639","row_version":2,"title":"손에 드는 미래형 정보판","original":"Data Pad","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"미래 세계의 인물이 얇은 판 모양의 휴대용 컴퓨터로 정보를 읽고 기록한다. 오늘날 태블릿과 닮은 장치가 일상 기술처럼 쓰인다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-006639/index.html"},{"id":"MEJE-KW-006640","row_version":2,"title":"공개되기도 전에 낡아 버린 작품","original":"Dated Before Release","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"제작 중에는 시의적절했던 현실 사건이나 사실이 작품 공개 전 바뀌어 대사와 설정이 어긋난다. 제작과 배급 사이의 시간이 작품을 뒤처지게 만든다. 공개 전에 현실이 바뀌는 경우와 달리 공개 뒤 연구 결과가 역사 묘사를 낡게 만들면 새 발견 때문에 낡은 역사 묘사이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006640/index.html"},{"id":"MEJE-KW-006641","row_version":2,"title":"새 발견 때문에 낡은 역사 묘사","original":"Dated History","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품을 만들 당시 정설로 여긴 역사 해석이 이후의 연구로 바뀌어 화면의 과거가 낡아 보인다. 제작 당시의 지식과 현재의 지식이 어긋난다. 역사 해석의 변화가 제작과 공개 사이에 일어나면 공개되기도 전에 낡아 버린 작품에 해당한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006641/index.html"},{"id":"MEJE-KW-006642","row_version":1,"title":"날짜가 빠진 묘비","original":"Dateless Grave","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"영상 속 묘비에 태어난 날과 죽은 날을 비워 두어 시대나 나이의 구체적 단서를 줄인다. 작품이 정한 시간의 모호함을 유지하는 배경 연출이다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-006642/index.html"},{"id":"MEJE-KW-006643","row_version":1,"title":"기사 머리에 붙는 장소와 날짜","original":"Dateline","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"신문·방송 보도의 첫머리에 사건이 일어난 장소와 날짜를 표시한다. 독자가 기사의 시점과 지역을 빠르게 파악하게 한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-006643/index.html"},{"id":"MEJE-KW-006644","row_version":2,"title":"온라인 가면과 연애하기","original":"Date My Avatar","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"온라인에서 꾸며 낸 정체성에 끌린 인물이 실제 상대를 만나면서 보였던 모습과 살아 있는 사람이 다를 수 있음을 깨닫는다. 익명성과 기대가 관계의 신뢰를 흔든다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006644/index.html"},{"id":"MEJE-KW-006645","row_version":1,"title":"몰래 지켜보는 데이트","original":"Date Peepers","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"두 사람의 데이트를 주변 친구나 가족이 숨어서 구경하거나 간섭한다. 둘만의 만남에 예상 밖의 관객이 생겨 소동이 벌어진다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006645/index.html"},{"id":"MEJE-KW-006646","row_version":3,"title":"데이트 상대의 성폭력","original":"Date Rape","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"데이트 중 한 사람이 상대의 동의를 무시하고 성적 폭력을 가한다. 친밀한 관계라는 외양이 침해의 책임을 지우지 않는다는 점을 분명히 한다. 데이트 중 동의 침해가 더 이어지기 전에 중단되는 서사는 데이트 중 성폭력을 막아 내기으로 구분한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006646/index.html"},{"id":"MEJE-KW-006647","row_version":2,"title":"데이트 중 성폭력을 막아 내기","original":"Date Rape Averted","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"데이트 중 상대의 거부를 무시하는 행동이 이어지다가 당사자의 저항이나 제삼자의 개입으로 멈춘다. 위험의 회피와 피해자의 선택을 중심에 둔다. 동의를 무시한 성폭력이 이미 발생했다면 데이트 상대의 성폭력의 범위에 들어가므로 중단된 시점을 분명히 한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006647/index.html"},{"id":"MEJE-KW-006648","row_version":2,"title":"친구의 형제자매와 연애하기","original":"\"Dating Best Friend's Sibling\" Drama","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"인물이 가까운 친구의 형제자매와 사랑에 빠지며 익숙함과 망설임을 동시에 겪는다. 친구가 관계를 어떻게 받아들일지가 연애의 갈등이 된다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006648/index.html"},{"id":"MEJE-KW-006649","row_version":2,"title":"영웅과 악역 사이의 공개된 연애 감정","original":"Dating Catwoman","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"대립하는 영웅과 상대편 인물이 서로의 매력을 인정하며 연애 감정을 드러낸다. 싸움과 친밀함이 같은 만남 안에 놓인다. 영웅의 연애 상대가 악역 쪽 인물이라는 점에서는 악역의 연인의 관계와 겹친다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006649/index.html"},{"id":"MEJE-KW-006650","row_version":1,"title":"긴 연재에서 서로 연인이 되는 인물들","original":"Dating Do-Si-Do","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"시리즈가 오래 이어지며 같은 인물 집단 안에서 연애 상대가 계속 바뀐다. 새로운 인물을 들이지 않아도 관계의 조합이 이야기를 이어 간다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006650/index.html"},{"id":"MEJE-KW-006651","row_version":1,"title":"데이트를 중심으로 만든 회차","original":"Dating Episode","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"시리즈의 한 회차가 인물의 데이트 준비와 만남, 그 결과에 집중한다. 평소 다른 사건을 다루던 작품에서 연애의 변화가 전면에 선다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006651/index.html"},{"id":"MEJE-KW-006652","row_version":3,"title":"만남 서비스를 재난처럼 그리기","original":"Dating Service Disaster","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 소개 업체나 온라인 만남에서 만난 사람을 유난히 위험하거나 우스운 인물로 묘사한다. 자연스러운 만남만 정상이라는 시대적 편견을 반영할 수 있다. 온라인 만남에서 꾸민 정체성이 갈등의 핵심이면 온라인 가면과 연애하기의 이야기가 된다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-006652/index.html"},{"id":"MEJE-KW-006654","row_version":2,"title":"부모가 싫어할 상대와 데이트하기","original":"Dating What Daddy Hates","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"인물이 부모가 못마땅해할 상대와 일부러 만나거나 진심으로 가까워진다. 가족의 기대와 개인의 선택이 연애를 둘러싸고 부딪힌다. 부모의 반대와 별개로 상대가 가까운 친구의 형제자매라면 친구의 형제자매와 연애하기의 갈등도 생긴다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-006654/index.html"},{"id":"MEJE-KW-006655","row_version":1,"title":"작은 도전자가 거인을 이기기","original":"David Versus Goliath","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"몸집이나 힘에서 크게 밀리는 인물이 거대한 상대와 겨뤄 승리한다. 불리한 조건을 넘어서는 선택과 기지가 승부를 뒤집는다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006655/index.html"},{"id":"MEJE-KW-006656","row_version":1,"title":"데이비 존스","original":"Davy Jones","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":null,"parent_id":null,"tag_path":["ML-F29"],"summary":"서양의 선원 전승에서 바다 깊은 곳과 실종된 배의 운명을 떠올리게 하는 초자연적 존재다. 모습은 작품마다 달라도 피해야 할 바다의 힘으로 그려진다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006656/index.html"},{"id":"MEJE-KW-006657","row_version":1,"title":"동틀 무렵 시작되는 기습","original":"Dawn Attack","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"공격하는 쪽이 밤사이 다가가 첫빛이 생길 때 상대를 덮친다. 밤의 은폐와 새벽의 시야를 함께 이용하는 전투 장면이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006657/index.html"},{"id":"MEJE-KW-006658","row_version":1,"title":"새 시대의 시작을 알리는 사건","original":"Dawn of an Era","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"한 사건이 세계의 질서와 가능성을 좋은 방향으로 크게 바꾼다. 인물들이 이제부터의 삶은 이전과 다르리라는 사실을 깨닫는다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006658/index.html"},{"id":"MEJE-KW-006659","row_version":1,"title":"개척 초기의 북미 서부극","original":"Dawn of the Wild West","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"북미 서부를 다룬 작품 중 18세기 말부터 1840년대까지 탐험과 초기 정착의 시기를 무대로 삼는다. 익숙한 후기 서부 개척물보다 앞선 풍경과 갈등을 그린다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-006659/index.html"},{"id":"MEJE-KW-006660","row_version":1,"title":"학생 역을 맡은 성인 배우","original":"Dawson Casting","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"청소년 인물을 실제 학생보다 나이가 많은 성인 배우가 연기한다. 촬영 조건과 캐스팅의 선택이 등장인물의 외형을 바꾼다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006660/index.html"},{"id":"MEJE-KW-006661","row_version":1,"title":"아이 돌봄 시설의 악몽","original":"Daycare Nightmare","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"즐거워야 할 어린이집이나 보육 시설이 아이나 직원에게 괴로운 장소로 드러난다. 보호를 약속하는 공간과 실제 경험이 어긋난다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-006661/index.html"},{"id":"MEJE-KW-006662","row_version":2,"title":"좋아하는 허구 세계가 실제라고 믿는 팬","original":"Daydream Believer","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"팬이 좋아하는 작품의 인물과 사건이 다른 세계 어딘가에서 실제로 존재한다고 믿거나 가능성을 진지하게 여긴다. 허구와 현실의 경계를 팬의 해석이 넘나든다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-006662/index.html"},{"id":"MEJE-KW-006663","row_version":2,"title":"현실처럼 보였던 공상이 드러나기","original":"Daydream Surprise","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"관객이 실제 사건으로 보던 짧은 장면이 인물의 상상이나 낮꿈이었음이 뒤늦게 밝혀진다. 시점의 비밀이 기대했던 결과를 잠시 보여 준다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-006663/index.html"},{"id":"MEJE-KW-006664","row_version":1,"title":"어둠에 익숙해 햇빛이 괴로운 눈","original":"Day Hurts Dark-Adjusted Eyes","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"오랫동안 어두운 곳에 살던 인물이 보통의 낮빛에도 눈의 통증이나 불편을 겪는다. 어둠에 적응한 몸의 조건이 낮의 활동을 어렵게 한다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-006664/index.html"},{"id":"MEJE-KW-006665","row_version":2,"title":"인물의 평범한 하루를 따라가는 회차","original":"Day in the Life","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"시리즈의 한 회차가 큰 사건보다 등장인물의 일상적인 하루와 반복되는 일을 보여 준다. 평범한 생활을 통해 성격과 관계를 알아보게 한다. 평범한 하루를 본편에 담는 대신 시작 화면에서 짧게 소개하면 일상을 보여 주는 오프닝 크레딧이다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006665/index.html"},{"id":"MEJE-KW-006666","row_version":2,"title":"일상을 보여 주는 오프닝 크레딧","original":"\"Day in the Life\" Titles","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"시리즈의 오프닝에서 주요 인물들이 각자의 평범한 하루를 보내는 모습을 이어 보여 준다. 짧은 동작과 장소로 성격과 생활을 소개한다. 오프닝에서 잠깐 본 일상에 회차 전체가 머물면 인물의 평범한 하루를 따라가는 회차이 된다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006666/index.html"},{"id":"MEJE-KW-006667","row_version":3,"title":"대낮에 펼쳐지는 공포","original":"Daylight Horror","aliases":[],"kind":"keyword","facet_id":"ML-F19","node_kind":null,"parent_id":null,"tag_path":["ML-F19"],"summary":"숨을 어둠이 없는 밝은 낮에도 위협과 불안을 느끼게 하는 공포 연출이다. 충분히 볼 수 있다는 안도감이 깨지며 공포가 드러난다. 밝은 시간까지 위험이 이어지면 어두운 장소와 위협을 묶는 어둠 속에 들어가면 닥치는 위험의 기대가 뒤집힌다.","accent":"#9B7F74","tab":"#9A6A55","facet":"정서·톤","bookmark":"분류축","entry_url":"cards/MEJE-KW-006667/index.html"},{"id":"MEJE-KW-006668","row_version":2,"title":"알고 보니 쉬는 날","original":"Day Off All Along","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 지각한 줄 알고 출근이나 등교 준비를 서두른 뒤 그날이 휴일임을 깨닫는다. 헛된 분주함이 일상의 작은 반전이 된다. 일상의 평범한 아침을 따라가다가 휴일이라는 사실이 드러나면 인물의 평범한 하루를 따라가는 회차에 작은 반전을 얹는다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006668/index.html"},{"id":"MEJE-KW-006669","row_version":1,"title":"고향을 장악한 권위주의 세력","original":"Day of the Jackboot","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"인물의 나라나 도시가 강압적인 정치·군사 세력에게 넘어간다. 익숙한 일상이 통제와 두려움의 공간으로 바뀌며 저항의 이유가 생긴다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006669/index.html"},{"id":"MEJE-KW-006670","row_version":1,"title":"요일에서 딴 이름","original":"\"Day of the Week\" Name","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물에게 태어난 날이나 상징적인 요일의 이름을 붙인다. 평범한 달력의 말이 성격과 운명을 암시하는 이름이 된다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-006670/index.html"},{"id":"MEJE-KW-006671","row_version":1,"title":"만든 지 하루 된 물건에 붙은 옛 전설","original":"Day-Old Legend","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"방금 만든 물건의 설명에 수백 년 전부터 내려온 듯한 내력이 적혀 있다. 제작 시점과 전설의 시간이 맞지 않는 모순이 드러난다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-006671/index.html"},{"id":"MEJE-KW-006672","row_version":3,"title":"옛 사회 형태로 돌아간 미래","original":"Days of Future Past","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"우주선과 첨단 무기가 있어도 정치와 생활은 봉건 시대나 서부 개척 시대처럼 조직된 미래를 그린다. 기술의 진보와 사회 제도의 변화가 따로 움직인다. 미래 사회가 초기 북미 서부의 사회와 풍경을 본뜬다면 개척 초기의 북미 서부극의 시대감을 새 배경으로 옮긴 셈이다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-006672/index.html"},{"id":"MEJE-KW-006673","row_version":1,"title":"요일을 차례로 부르는 노래","original":"\"Days of the Week\" Song","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"한 주의 요일을 순서대로 열거하거나 각 요일에 짧은 이야기를 붙이는 노래다. 반복되는 목록이 기억과 리듬을 함께 만든다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-006673/index.html"},{"id":"MEJE-KW-006674","row_version":2,"title":"낮 드라마에 빠진 실직 남성","original":"Daytime Drama Queen","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 실직한 남성이 낮 시간 연속극을 즐기는 모습을 실패한 삶의 표시처럼 다룬다. 성별과 여가에 대한 편견을 이용하는 재현 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-006674/index.html"},{"id":"MEJE-KW-006675","row_version":1,"title":"햇빛 아래 걸을 수 있는 흡혈귀","original":"Daywalking Vampire","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"햇빛에 닿아도 죽거나 큰 해를 입지 않고 낮에 활동할 수 있는 흡혈귀다. 작품마다 낮에 약해지는 정도와 이유는 달라질 수 있다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-006675/index.html"},{"id":"MEJE-KW-006676","row_version":1,"title":"큰 가슴 때문에 겪는 불편","original":"D-Cup Distress","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 큰 가슴으로 인한 신체적 불편이나 원치 않는 시선 때문에 자기 몸을 힘들게 느낀다. 타인의 평가보다 당사자의 경험을 중심에 둔다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-006676/index.html"},{"id":"MEJE-KW-006677","row_version":1,"title":"방송 중 길어진 침묵","original":"Dead Air","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"라디오나 생방송에서 예정에 없던 침묵이 이어져 진행자와 제작진이 긴장한다. 소리가 비는 시간이 방송 사고처럼 느껴진다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-006677/index.html"},{"id":"MEJE-KW-006678","row_version":1,"title":"살아 있는 줄 알았던 인물의 죽음","original":"Dead All Along","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"평범하게 움직이던 인물이 사실은 이미 죽은 상태였음이 뒤늦게 밝혀진다. 관객과 인물의 앞선 장면 해석이 함께 바뀐다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006678/index.html"},{"id":"MEJE-KW-006679","row_version":2,"title":"다른 세계에서 이미 죽은 자기 자신","original":"Dead Alternate Counterpart","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"평행세계를 방문한 인물이 그곳의 자기 대응 인물이 이미 죽었다는 사실을 알게 된다. 가능한 다른 삶의 끝을 마주하며 자신을 돌아본다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-006679/index.html"},{"id":"MEJE-KW-006680","row_version":2,"title":"죽은 동물로 보내는 위협","original":"Dead Animal Warning","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"가해자가 죽은 동물을 상대에게 보여 주거나 남겨 다음 피해를 암시한다. 생명을 해친 흔적이 말보다 강한 협박으로 쓰인다. 경고의 대상이 동물이 아니라 사람의 몸이라면 사람들 앞에 남겨진 시신의 위협적인 공개 방식과 맞닿는다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006680/index.html"},{"id":"MEJE-KW-006681","row_version":2,"title":"죽어야 인정받는 예술가라는 관습","original":"Dead Artists Are Better","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 예술가는 살아 있을 때 외면받다가 사후에야 천재로 인정된다고 그린다. 실제 예술사의 다양한 경우를 하나의 통념으로 압축한 표현이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-006681/index.html"},{"id":"MEJE-KW-006682","row_version":2,"title":"죽은 사람을 집에 계속 두기","original":"Dead Body Roommate","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 죽은 사람의 몸을 집에 남겨 둔 채 일상을 이어 간다. 상실을 받아들이지 못하거나 범행을 숨기는 심리가 공간에 드러난다. 시신을 숨기지 않고 사람들 앞에 놓는 경우는 사람들 앞에 남겨진 시신의 모습이 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006682/index.html"},{"id":"MEJE-KW-006683","row_version":1,"title":"죽었는데도 움직이는 게임 캐릭터","original":"Dead Character Walking","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임에서 죽음 판정이 났는데 오류나 규칙의 빈틈으로 인물이나 적이 계속 행동한다. 상태와 화면의 불일치가 예기치 않은 플레이를 만든다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006683/index.html"},{"id":"MEJE-KW-006684","row_version":1,"title":"서로 만나지 않고 전달하는 비밀 물건","original":"Dead Drop","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"서로 얼굴을 보이지 않으려는 두 사람이 한 장소에 물건을 두고 시간을 달리해 주고받는다. 전달 장소가 비밀 연락의 매개가 된다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006684/index.html"},{"id":"MEJE-KW-006685","row_version":1,"title":"새 인물이 오래 버티지 못하는 자리","original":"Dead-End Job","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"연재물의 특정 직책에 새 인물이 반복해서 들어왔다가 짧은 이야기 뒤에 떠난다. 같은 자리가 계속 새로운 인물과 갈등을 들이는 통로가 된다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006685/index.html"},{"id":"MEJE-KW-006686","row_version":2,"title":"나갈 길이 없는 게임 방","original":"Dead-End Room","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임의 미로에서 들어갈 수는 있지만 밖으로 이어지는 통로가 없는 방에 갇힌다. 진행을 막는 설계가 함정이나 막다른 선택이 된다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-006686/index.html"},{"id":"MEJE-KW-006687","row_version":1,"title":"다시는 되살아나지 못하는 죽음","original":"Deader than Dead","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"죽은 인물이 자주 돌아오는 세계에서도 어떤 죽음은 되돌릴 수 없다고 정한다. 반복된 부활의 기대를 끝내는 서사적 규칙이다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-006687/index.html"},{"id":"MEJE-KW-006688","row_version":1,"title":"업데이트가 끊긴 팬소설","original":"Dead Fic","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"온라인 팬소설의 새 장이 점점 늦어지다가 끝내 올라오지 않는다. 독자는 결말을 기다린 채 멈춘 이야기를 기억한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-006688/index.html"},{"id":"MEJE-KW-006689","row_version":1,"title":"운전자가 쓰러져 계속 달리는 차","original":"Dead Foot Leadfoot","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"차를 몰던 인물이 의식을 잃거나 죽은 뒤에도 차량이 속도를 내며 움직인다. 제어할 사람이 사라진 탈것이 새로운 위험이 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006689/index.html"},{"id":"MEJE-KW-006690","row_version":1,"title":"죽은 사람의 이름을 이어받은 아이","original":"Dead Guy Junior","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"새로 태어난 아이에게 먼저 세상을 떠난 가족이나 가까운 사람의 이름을 붙인다. 이름이 애도와 기억을 다음 세대로 옮긴다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-006690/index.html"},{"id":"MEJE-KW-006691","row_version":2,"title":"사람들 앞에 남겨진 시신","original":"Dead Guy on Display","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"죽은 사람의 몸이 묻히지 않고 공개된 장소에 놓여 경고나 추모의 상징이 된다. 시신을 대하는 방식이 남은 이들의 권력과 믿음을 드러낸다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-006691/index.html"},{"id":"MEJE-KW-006692","row_version":1,"title":"시신 인형극","original":"Dead Guy Puppet","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"죽은 인물의 몸을 인형처럼 움직여 다른 인물을 위협하거나 조롱하는 장면이다. 생존자의 충격과 가해자의 잔혹성을 강조한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006692/index.html"},{"id":"MEJE-KW-006693","row_version":3,"title":"늘어진 손으로 알리는 죽음","original":"Dead-Hand Shot","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물의 힘없이 늘어진 손을 클로즈업해 죽음이나 심각한 부상을 암시한다. 영화 장면뿐 아니라 포스터와 표지에서도 전신을 보이지 않고 상황을 전하는 구도로 쓰인다. 사람을 직접 보여 주지 않고 죽음을 암시하는 연출에는 남겨진 모자로 암시하는 죽음도 있다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-006693/index.html"},{"id":"MEJE-KW-006694","row_version":1,"title":"남겨진 모자로 암시하는 죽음","original":"Dead Hat Shot","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물의 모자 같은 소지품을 현장에 홀로 남겨 죽음이나 실종을 암시한다. 뒤에 생존 사실이 드러나면 이 암시가 반전으로 작동한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-006694/index.html"},{"id":"MEJE-KW-006695","row_version":2,"title":"진부함마저 진부한 클리셰","original":"Dead Horse Trope","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"어떤 표현이 너무 낡았다고 비틀거나 조롱하는 방식 자체가 반복되어 새로움을 잃은 경우다. 관습을 피하려는 반응도 다시 관습이 될 수 있음을 보여 준다. 반복된 풍자라는 점에서는 존재하지 않았던 클리셰의 종말와 맞닿지만, 실제로 널리 쓰였던 표현인지가 다르다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-006695/index.html"},{"id":"MEJE-KW-006696","row_version":1,"title":"뉴스가 된 취재자","original":"Deadline News","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"사건을 전하던 기자나 진행자가 그 사건의 피해자가 되면서 보도의 대상이 바뀌는 전개다. 취재 현장과 재난 사이의 거리를 한순간에 무너뜨린다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006696/index.html"},{"id":"MEJE-KW-006697","row_version":2,"title":"목욕 중 벌어진 죽음","original":"Deadly Bath","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 목욕이나 샤워 중 습격을 받거나 사고를 겪어 목숨을 잃는 장면이다. 사적인 공간의 안전감이 깨지는 효과를 낸다. 죽음이 다가왔음을 몸의 작은 변화로 알리는 방식은 죽음을 예고하는 코피와 연결된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-006697/index.html"},{"id":"MEJE-KW-006698","row_version":1,"title":"위험한 책","original":"Deadly Book","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"읽거나 쓰는 행위가 초자연적 위해를 일으키거나 책 자체가 위협이 되는 설정이다. 지식의 매개체가 위험의 근원으로 뒤집힌다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-006698/index.html"},{"id":"MEJE-KW-006699","row_version":2,"title":"엔딩 직전의 죽음","original":"Deadly Closing Credits","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"이야기가 끝나고 자막이 오르기 직전에 인물이 죽거나 치명적인 공격을 받는다. 마무리될 듯한 분위기를 깨고 후속 전개에 긴장을 남긴다. 죽음을 예고하는 시점과 장면 구성에 따라 회상 뒤에 찾아오는 죽음와 구분된다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-006699/index.html"},{"id":"MEJE-KW-006700","row_version":2,"title":"미뤄 둔 대화의 영원한 부재","original":"Deadly Deferred Conversation","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"중요한 이야기를 다음 만남으로 미뤘다가 한쪽의 죽음이나 실종으로 끝내 나누지 못한다. 남겨진 말이 후회와 미해결 갈등의 중심이 된다. 나누지 못한 말이 사후에 전해진다면 죽은 사람이 남긴 글의 형태를 띤다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006700/index.html"},{"id":"MEJE-KW-006701","row_version":1,"title":"배달원으로 위장한 가해자의 접근","original":"Deadly Delivery","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"가해자가 배달원으로 위장해 평범한 배달 상황을 위협적인 대면으로 바꾸는 전개. 익숙한 절차가 경계심을 낮추는 서사적 역할을 한다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-006701/index.html"},{"id":"MEJE-KW-006702","row_version":2,"title":"사나운 딩고 묘사","original":"Deadly Dingos","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"호주의 야생견 딩고를 유난히 흉포하고 사람을 노리는 동물로 그리는 관습이다. 현실 동물에 관한 사실보다는 작품 속 과장된 이미지에 해당한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-006702/index.html"}]}.cards;